 if exists(select 1 from public.course_modules m where m.id=any(candidate) and (exists(select 1 from public.lessons l join public.lesson_progress p on p.lesson_id=l.id where l.module_id=m.id) or exists(select 1 from public.activities a join public.submissions s on s.activity_id=a.id where a.module_id=m.id) or exists(select 1 from public.activities a join public.activity_progress p on p.activity_id=a.id where a.module_id=m.id) or exists(select 1 from public.activities a join public.practice_logs p on p.activity_id=a.id where a.module_id=m.id) or exists(select 1 from public.activities a join public.portfolio_projects p on p.activity_id=a.id where a.module_id=m.id) or exists(select 1 from public.xp_ledger x where x.module_id=m.id) or exists(select 1 from public.module_instructional_media im where im.module_id=m.id))) or exists(select 1 from public.certificates where course_id=v_course) then raise exception 'Rollback blocked by Piano evidence or dependencies';end if;
 if exists(select 1 from public.course_modules where id=any(candidate) and (course_id<>v_course or status<>'draft' or review_notes not like 'Piano full draft rollout 202608130001;%' or core_xp<>625 or intro_core_xp<>50 or video_core_xp<>100 or assignment_core_xp<>350 or mastery_core_xp<>125 or core_unlock_threshold<>438 or lab_tool_id is not null or active_instructional_media_id is not null)) then raise exception 'Rollback module candidate payload drift';end if;
 if exists(select 1 from public.lessons where module_id=any(candidate) and (status<>'draft' or xp_value<>0 or sort_order not between 1 and 3)) then raise exception 'Rollback lesson candidate payload drift';end if;
 if exists(select 1 from public.activities where module_id=any(candidate) and not((activity_type='practice' and xp_type='bonus' and xp_reward=0 and not required and status='draft') or (activity_type='performance' and xp_type='core' and xp_reward=350 and required and status='draft' and passing_score=70 and allows_resubmission))) then raise exception 'Rollback activity candidate payload drift';end if;
 delete from public.activities where module_id=any(candidate) and id in(select (value->>'practice')::uuid from jsonb_each(v_ids) union all select (value->>'challenge')::uuid from jsonb_each(v_ids));
 delete from public.lessons where module_id=any(candidate) and id in(select (x#>>'{}')::uuid from jsonb_each(v_ids),jsonb_array_elements(value->'lessons') x);
 delete from public.course_modules where id=any(candidate) and review_notes like 'Piano full draft rollout 202608130001;%';
 delete from public.course_levels l where l.course_id=v_course and l.level_number in(2,3,4) and l.review_notes='Piano full draft rollout 202608130001; metadata target reconciliation deferred.' and not exists(select 1 from public.course_modules m where m.course_level_id=l.id);
 if not exists(select 1 from public.course_modules m join public.course_levels l on l.id=m.course_level_id where m.course_id=v_course and l.level_number=1 and m.level_module_number=1 and m.title='Piano Posture and Hand Position') then raise exception 'Module 1 preservation invariant failed';end if;
end $$;commit;
